+// stopSequences maps the OpenAI stop field onto Cohere stop_sequences.
+// OpenAI accepts a string or an array; non-strings inside an array are ignored.
+func stopSequences(stop any) []string {
+	switch v := stop.(type) {
+	case string:
+		return []string{v}
+	case []string:
+		if len(v) == 0 {
+			return nil
+		}
+
+		return v
+	case []any:
+		out := make([]string, 0, len(v))
+		for _, item := range v {
+			s, ok := item.(string)
+			if !ok {
+				continue
+			}
+
+			out = append(out, s)
+		}
+
+		if len(out) == 0 {
+			return nil
+		}
+
+		return out
+	default:
+		return nil
+	}
+}
